using Alterverse.Characters;using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class HeroPresenceVFX:MonoBehaviour
{
private HeroIdentity identity;private Transform root;private Transform[] motes;private Vector3[] origins;private Renderer visibilityRenderer;private MaterialPropertyBlock colorBlock;private static readonly int BaseColor=Shader.PropertyToID("_BaseColor"),ColorId=Shader.PropertyToID("_Color");private void Start(){identity=GetComponent<HeroIdentity>();root=transform.Find("DF_VisualRoot");if(identity==null||root==null)return;visibilityRenderer=root.GetComponentInChildren<Renderer>();Color accent=StylizedArtDirection.HeroAccent(identity.Hero);int count=(identity.Hero==HeroId.Kaelon||identity.Hero==HeroId.Rook)?3:5;motes=new Transform[count];origins=new Vector3[count];for(int i=0;i<count;i++){GameObject g=GameObject.CreatePrimitive(i%2==0?PrimitiveType.Cube:PrimitiveType.Sphere);g.name="DF_PresenceMote";g.transform.SetParent(root,false);float a=i*Mathf.PI*2/count;Vector3 p=new Vector3(Mathf.Cos(a)*(.48f+.08f*(i%2)),.12f+i*.11f,Mathf.Sin(a)*(.48f+.08f*(i%2)));g.transform.localPosition=p;float moteSize=identity.Hero==HeroId.Rook?.07f:.045f;g.transform.localScale=Vector3.one*moteSize;Collider c=g.GetComponent<Collider>();if(c!=null){c.enabled=false;Object.Destroy(c);}Renderer r=g.GetComponent<Renderer>();if(r!=null){r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.receiveShadows=false;colorBlock??=new MaterialPropertyBlock();colorBlock.Clear();Color mote=Color.Lerp(accent,Color.white,.18f);colorBlock.SetColor(BaseColor,mote);colorBlock.SetColor(ColorId,mote);r.SetPropertyBlock(colorBlock);}motes[i]=g.transform;origins[i]=p;}}
private void LateUpdate(){if(motes==null||identity==null||Time.timeScale<=0f||(visibilityRenderer!=null&&!visibilityRenderer.isVisible))return;float t=Time.time,dt=Time.deltaTime;for(int i=0;i<motes.Length;i++){Transform m=motes[i];if(m==null)continue;Vector3 p=origins[i];switch(identity.Hero){case HeroId.Veyr:p.x+=Mathf.Sin(t*3+i)*.13f;p.y+=Mathf.Repeat(t*.24f+i*.18f,.55f);break;case HeroId.Nyra:p.z+=Mathf.Sin(t*2.4f+i)*.1f;p.y+=Mathf.Sin(t*1.7f+i)*.05f;break;case HeroId.Elyra:float a=t*1.1f+i*Mathf.PI*2/motes.Length;p=new Vector3(Mathf.Cos(a)*.62f,.3f+Mathf.Sin(a*1.7f)*.22f,Mathf.Sin(a)*.62f);break;case HeroId.Mira:p.y+=Mathf.Sin(t*1.5f+i)*.14f;p.x*=1+Mathf.Sin(t+i)*.12f;break;case HeroId.Kaelon:p.y=.15f+i*.18f;p.x=Mathf.Sign(p.x)*.5f;break;default:p.y+=Mathf.Abs(Mathf.Sin(t*2+i))*.08f;p.x+=Mathf.Sin(t*1.4f+i)*.05f;break;}m.localPosition=p;m.Rotate(25*dt,42*dt,18*dt,Space.Self);}}
}
